{"files":{"tokenizer.js":"function normalize(text) {
  return text.normalize('NFKC').replace(/\s+/g, ' ').trim();
}

function tokenize(text) {
  const normalized = normalize(text);
  const tokens = [];
  let current = '';
  for (let i = 0; i < normalized.length; i++) {
    const ch = normalized[i];
    if (/[A-Za-z0-9]/.test(ch)) {
      current += ch;
    } else if (ch === "'") {
      if (current !== '') {
        tokens.push(current);
        current = '';
      }
      // apostrophe acts as separator; if current is empty, ignore it
    } else {
      if (current !== '') {
        tokens.push(current);
        current = '';
      }
      // any other character (including accented letters after NFKC) is a separator
    }
  }
  if (current !== '') {
    tokens.push(current);
  }
  return tokens;
}

function analyze(text) {
  const tokens = tokenize(text);
  const unique = [];
  const seen = new Set();
  const frequencies = {};
  for (const token of tokens) {
    if (!seen.has(token)) {
      seen.add(token);
      unique.push(token);
    }
    frequencies[token] = (frequencies[token] || 0) + 1;
  }
  const count = tokens.length;
  const uniqueCount = unique.length;
  const summary = count + ' tokens; ' + uniqueCount + ' unique';
  return { tokens: tokens, count: count, unique: unique, frequencies: frequencies, summary: summary };
}
